const body = $json.body;
const exactKeys = ['schema_version', 'session_id', 'turn_id', 'transcript'];
const idPattern = /^[A-Za-z0-9][A-Za-z0-9._:-]{7,127}$/;
if (!body || typeof body !== 'object' || Array.isArray(body)) throw new Error('invalid_request');
if (Object.keys(body).sort().join(',') !== exactKeys.sort().join(',')) throw new Error('invalid_request');
if (body.schema_version !== '1') throw new Error('invalid_request');
if (typeof body.session_id !== 'string' || body.session_id.length > 128 || !idPattern.test(body.session_id)) throw new Error('invalid_request');
if (typeof body.turn_id !== 'string' || body.turn_id.length > 80 || !idPattern.test(body.turn_id)) throw new Error('invalid_request');
if (typeof body.transcript !== 'string' || body.transcript.length < 1 || body.transcript.length > 2000) throw new Error('invalid_request');
return [{ json: body }];

const request = $('Validate Jarvis Turn').item.json;
const choices = Array.isArray($json.choices) ? $json.choices : [];
const message = choices.length === 1 && choices[0] && typeof choices[0] === 'object' ? choices[0].message : null;
const output = message && typeof message === 'object' ? message.content : null;
if (typeof output !== 'string' || output.trim().length < 1 || output.length > 4000) throw new Error('invalid_model_output');
return [{ json: {
  schema_version: '1',
  session_id: request.session_id,
  turn_id: request.turn_id,
  status: 'complete',
  spoken_text: output.trim(),
  tool_results: [],
} }];
